//! Cross-engine timing on the large sparse-parity record programs:
//! Rust CPU (Rayon) and GPU (LDS) over batch sizes 1k/10k/100k, for
//! the comparison table linked from the sparse-parity site.
//!
//! Programs are read from /tmp/large-progs/*.ir (generated by the
//! Python reference); instance rows are synthetic (evaluation cost is
//! instance-independent for the interpreter).

use std::fs;
use std::time::Instant;

use dally_eval::ir::Program;
use dally_eval::runner::BatchRunner;
use dally_eval::{CpuRunner, LdsRunner};

fn synth(prog: &Program, n: usize) -> Vec<u8> {
    let width = prog.inputs.len();
    let mut s = 0x5EED_5EED_5EED_5EEDu64;
    let mut v = vec![0u8; n * width];
    for b in v.iter_mut() {
        s = s
            .wrapping_mul(6364136223846793005)
            .wrapping_add(1442695040888963407);
        *b = (s >> 33) as u8;
    }
    v
}

fn main() {
    let dir = concat!(env!("CARGO_MANIFEST_DIR"), "/.bench");
    let names = [
        "packedsis_cap2_seed0",
        "packedwalk_40",
        "packedsis_cap3_seed0",
        "weightscan3_80pct",
        "weightscan5_100pct",
    ];
    for name in names {
        let text = match fs::read_to_string(format!("{dir}/{name}.ir")) {
            Ok(t) => t,
            Err(_) => {
                eprintln!("SKIP {name}: no IR file");
                continue;
            }
        };
        let prog = Program::parse(&text).expect("parse");
        println!(
            "{name}: ops {:>8}  cost {:>10}",
            prog.len(),
            prog.static_cost
        );
        for &n in &[1_000usize, 10_000, 100_000] {
            let inputs = synth(&prog, n);
            // CPU Rayon
            let t0 = Instant::now();
            let _ = CpuRunner.run_batch(&prog, &inputs, n).unwrap();
            let cpu = t0.elapsed();
            // GPU LDS (if runner fits)
            // GPU: chunked dispatch keeps bindings under the storage
            // cap at any batch size (see LdsRunner::run)
            let gpu = (|| {
                let r = LdsRunner::new(&prog, n).ok()?;
                r.run(&prog, &inputs, n)
                    .map_err(|e| {
                        eprintln!("gpu first-run err: {e:?}");
                        e
                    })
                    .ok()?;
                let t0 = Instant::now();
                r.run(&prog, &inputs, n).ok()?;
                Some(t0.elapsed())
            })();
            match gpu {
                Some(g) => println!(
                    "  n={n:>6}: cpu {cpu:>9.3?} ({:>7.0}/s)  gpu {g:>9.3?} ({:>7.0}/s)",
                    n as f64 / cpu.as_secs_f64(),
                    n as f64 / g.as_secs_f64(),
                ),
                None => println!(
                    "  n={n:>6}: cpu {cpu:>9.3?} ({:>7.0}/s)  gpu n/a",
                    n as f64 / cpu.as_secs_f64(),
                ),
            }
        }
    }
}
